def _cov_query(c, fn, p, cap):
    buf = (ctypes.c_double * cap)()
    n = fn(c, p, buf, cap)
    if n < 0:
        raise AraelError(
            n, (_f.path_cov_error(c) or b"").decode())
    return buf


def _shape_1(buf):
    return float(buf[0])


def _shape_2(buf):
    return _m.matrix2d.from_elements(buf[0], buf[1], buf[2], buf[3])


def _shape_3(buf):
    return _m.matrix3d.from_elements(*[buf[i] for i in range(9)])


def _shape_n(buf, n):
    return tuple(tuple(buf[r * n + c] for c in range(n)) for r in range(n))


class Covariance:
    """An assembled covariance, OWNED: released on garbage
    collection (free() to force it), independent of later assemblies.
    Per-entity queries (marginal/conditional by param count: 1 ->
    float, 2/3 -> matrix2d/3d, larger -> row-major tuples). Entity
    arguments must come from the live model."""

    __slots__ = ("_h",)

    def __init__(self, h):
        self._h = h

    def plan(self):
        """What the assembly decided -- the ordering it kept, what the
        candidates priced at, and how many symbolics it built."""
        p = CovPlan()
        _f.path_cov_plan(self._h, ctypes.byref(p))
        return p

    def free(self):
        if self._h:
            _f.path_cov_free(self._h)
            self._h = None

    def __del__(self):
        try:
            self.free()
        except Exception:
            pass

    def marginal(self, e):
        """The entity's marginal covariance block."""
        if isinstance(e, Landmark):
            return (_shape_2)(_cov_query(self._h, _f.path_landmark_marginal_cov, e._p, 4))
        if isinstance(e, Pose):
            return (_shape_3)(_cov_query(self._h, _f.path_pose_marginal_cov, e._p, 9))
        raise TypeError("no marginal for %r" % (e,))

    def conditional(self, e):
        """Conditional covariance (all other parameters fixed)."""
        if isinstance(e, Landmark):
            return (_shape_2)(_cov_query(self._h, _f.path_landmark_conditional_cov, e._p, 4))
        if isinstance(e, Pose):
            return (_shape_3)(_cov_query(self._h, _f.path_pose_conditional_cov, e._p, 9))
        raise TypeError("no conditional for %r" % (e,))

    def std_dev(self, e):
        """Per-parameter standard deviations (every CovMode, incl.
        TriDiagonal)."""
        if isinstance(e, Landmark):
            return list(_cov_query(self._h, _f.path_landmark_std_dev, e._p, 2))
        if isinstance(e, Pose):
            return list(_cov_query(self._h, _f.path_pose_std_dev, e._p, 3))
        raise TypeError("no std_dev for %r" % (e,))
    def _cross_landmark_landmark(self, a, b):
        buf = (ctypes.c_double * 4)()
        rows = _f.path_landmark_landmark_cross_cov(self._h, a._p, b._p, buf, 4)
        if rows < 0:
            raise AraelError(
                rows, (_f.path_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 2 + c] for c in range(2))
                     for r in range(rows))
    def _cross_landmark_pose(self, a, b):
        buf = (ctypes.c_double * 6)()
        rows = _f.path_landmark_pose_cross_cov(self._h, a._p, b._p, buf, 6)
        if rows < 0:
            raise AraelError(
                rows, (_f.path_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 3 + c] for c in range(3))
                     for r in range(rows))
    def _cross_pose_landmark(self, a, b):
        buf = (ctypes.c_double * 6)()
        rows = _f.path_pose_landmark_cross_cov(self._h, a._p, b._p, buf, 6)
        if rows < 0:
            raise AraelError(
                rows, (_f.path_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 2 + c] for c in range(2))
                     for r in range(rows))
    def _cross_pose_pose(self, a, b):
        buf = (ctypes.c_double * 9)()
        rows = _f.path_pose_pose_cross_cov(self._h, a._p, b._p, buf, 9)
        if rows < 0:
            raise AraelError(
                rows, (_f.path_cov_error(self._h) or b"").decode())
        return tuple(tuple(buf[r * 3 + c] for c in range(3))
                     for r in range(rows))

    def cross(self, a, b):
        """Row-major cross-covariance block between two entities."""
        if isinstance(a, Landmark) and isinstance(b, Landmark):
            return self._cross_landmark_landmark(a, b)
        if isinstance(a, Landmark) and isinstance(b, Pose):
            return self._cross_landmark_pose(a, b)
        if isinstance(a, Pose) and isinstance(b, Landmark):
            return self._cross_pose_landmark(a, b)
        if isinstance(a, Pose) and isinstance(b, Pose):
            return self._cross_pose_pose(a, b)
        raise TypeError("no cross-covariance for %r x %r" % (a, b))


